from collections import deque
def comps(g,val):
    seen=set(); out=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c]==val and (r,c) not in seen:
                q=deque([(r,c)]);seen.add((r,c));cells=[]
                while q:
                    a,b=q.popleft();cells.append((a,b))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            x,y=a+dr,b+dc
                            if 0<=x<len(g) and 0<=y<len(g[0]) and g[x][y]==val and (x,y) not in seen:
                                seen.add((x,y));q.append((x,y))
                out.append(cells)
    return out
