def ccomps(I,val):
    H,W=len(I),len(I[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if I[r][c]==val and (r,c) not in seen:
                q=[(r,c)];seen.add((r,c));cells=[]
                while q:
                    a,b=q.pop();cells.append((a,b))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr,b+dc
                        if 0<=x<H and 0<=y<W and I[x][y]==val and (x,y) not in seen:
                            seen.add((x,y));q.append((x,y))
                out.append(cells)
    return out
