def run_analysis(I,O):
    H=len(I); W=len(I[0])
    def four_connected_comp_cells(grid,value):
        seen=set(); out=[]
        for r in range(H):
            for c in range(W):
                if grid[r][c]==value and (r,c) not in seen:
                    stk=[(r,c)]; seen.add((r,c)); collected=[]
                    while stk:
                        a,b=stk.pop(); collected.append((a,b))
                        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                            x,y=a+dr,b+dc
                            if 0<=x<H and 0<=y<W and grid[x][y]==value and (x,y) not in seen:
                                seen.add((x,y)); stk.append((x,y))
                    out.append(collected)
        return out
    def get_norm(cells):
        mr=min(r for r,_ in cells); mc=min(c for _,c in cells)
        return tuple(sorted((r-mr,c-mc) for r,c in cells))
    def edge_reach(cells,H,W):
        return any(r==0 or r==H-1 or c==0 or c==W-1 for r,c in cells)
    diff=[(r,c,I[r][c],O[r][c]) for r in range(H) for c in range(W) if I[r][c]!=O[r][c]]
    tgt_new=diff[0][3]
    colors=sorted(set(x for row in I for x in row)-{I[0][0]})
    print("=== demo pair analysis")
    print("tgt new color:",tgt_new,"ndiff",len(diff))
    for col in colors:
        comps_of_color=four_connected_comp_cells(I,col)
        norms_map={}
        for idx,cp in enumerate(comps_of_color):
            nm=get_norm(cp)
            norms_map.setdefault(nm,[]).append((idx,len(cp),edge_reach(cp)))
        changed_idx={idx for idx,cp in enumerate(comps_of_color) if any(cell in {(d[0],d[1]) for d in diff} for cell in cp)}
        # For each changed comp find twins (same shape same or different color incl own color other comps)
        for idx in changed_idx:
            cp=comps_of_color[idx]
            nm=get_norm(cp)
            twins=[(v2,s2,e2) for v2 in colors for s2,e2 in norms_map.get(nm,[()])[0:1]]  # placeholder filled below
            twin_info=[]
