            # simpler: recompute all comps per color with shapes & tb
            tinfo=[]
            for v2 in colors:
                for idx2,c2_ in enumerate(four_connected_comp_cells(I,v2)):
                    nm2=get_norm(c2_)
                    if nm2==nm:
                        tinfo.append((v2,len(c2_),edge_reach(c2_),changed_idx.intersection({idx2})))
            print(f"col {col}: changed comp idx{idx} sz{len(cp)} tb{edge_reach(cp)} -> {tgt_new}; same-shape members incl itself:")
